def transform(grid):
    g=[r[:] for r in grid]
    # Complete each horizontal bar's one-cell break, then extend its color
    # along the break column until the next horizontal bar.
    anchors={}
    for r,row in enumerate(grid):
        nz=[c for c,v in enumerate(row) if v]
        if len(nz)>=2 and len({row[c] for c in nz})==1:
            color=row[nz[0]]
            holes=[c for c in range(nz[0],nz[-1]+1) if row[c]==0]
            for c in holes:
                g[r][c]=color
                anchors.setdefault(c,[]).append((r,color))
    for c,aa in anchors.items():
        aa.sort()
        for (r,col),(rn,coln) in zip(aa,aa[1:]):
            for y in range(r+1,rn):
                if grid[y][c]==0: g[y][c]=coln
        r,col=aa[0]
        for y in range(r):
            if grid[y][c]==0: g[y][c]=col
        last,_=aa[-1]
        for y in range(last+1,len(grid)):
            if grid[y][c]==0:
                g[y][c]=next((grid[z][c] for z in range(len(grid)-1,last,-1) if grid[z][c]), 0)
    return g
